// App.js - Dashboard con porcentaje (%) y altura configurable
// Sin decimales y sin botón de simulación

import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Typography, 
  Grid, 
  Slider, 
  Button, 
  Alert, 
  CircularProgress,
  Box,
  Divider,
  Chip,
  LinearProgress,
  TextField,
  InputAdornment
} from '@mui/material';
import { 
  ResponsiveContainer,
  AreaChart,
  Area,
  PieChart,
  Pie,
  Cell,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip as RechartsTooltip
} from 'recharts';
import { io } from 'socket.io-client';

// Configuración
const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:3001';
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';

// Colores profesionales
const COLORS = {
  primary: '#2563eb',
  success: '#10b981',
  warning: '#f59e0b',
  danger: '#ef4444',
  info: '#3b82f6',
  dark: '#1f2937',
  light: '#f3f4f6',
  white: '#ffffff'
};

function App() {
  const [status, setStatus] = useState({
    level: 0,
    pumpStatus: false,
    minLevel: 20,
    maxLevel: 80,
    tankHeight: 100
  });
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [alert, setAlert] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(new Date());
  
  // Estados para inputs
  const [inputMinLevel, setInputMinLevel] = useState('');
  const [inputMaxLevel, setInputMaxLevel] = useState('');
  const [inputTankHeight, setInputTankHeight] = useState('');

  useEffect(() => {
    // Crear conexión WebSocket
    const socket = io(SOCKET_URL);

    socket.on('status_update', (data) => {
      setStatus(data);
      setLastUpdate(new Date());
      checkAlerts(data);
    });

    fetchInitialData();
    
    return () => socket.close();
  }, []);

  const fetchInitialData = async () => {
    try {
      const statusRes = await fetch(`${API_URL}/api/status`);
      const statusData = await statusRes.json();
      setStatus(statusData);
      setInputMinLevel(statusData.minLevel.toString());
      setInputMaxLevel(statusData.maxLevel.toString());
      setInputTankHeight(statusData.tankHeight.toString());

      const historyRes = await fetch(`${API_URL}/api/history`);
      const historyData = await historyRes.json();
      setHistory(historyData);
    } catch (error) {
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const checkAlerts = (data) => {
    if (data.level <= 15) {
      setAlert({ type: 'error', message: '⚠️ ALARMA CRÍTICA: Nivel de agua MUY BAJO (15%)' });
    } else if (data.level >= 90) {
      setAlert({ type: 'error', message: '⚠️ ALARMA CRÍTICA: Tanque casi lleno (90%)' });
    } else if (data.level <= data.minLevel) {
      setAlert({ type: 'warning', message: `⚠️ Nivel bajo (${Math.round(data.level)}%): Bomba ENCENDIDA` });
    } else if (data.level >= data.maxLevel) {
      setAlert({ type: 'warning', message: `✅ Nivel alto (${Math.round(data.level)}%): Bomba APAGADA` });
    } else {
      setAlert(null);
    }
  };

  const saveConfig = async () => {
    const minVal = inputMinLevel === '' ? status.minLevel : parseInt(inputMinLevel);
    const maxVal = inputMaxLevel === '' ? status.maxLevel : parseInt(inputMaxLevel);
    const heightVal = inputTankHeight === '' ? status.tankHeight : parseInt(inputTankHeight);
    
    if (minVal >= maxVal) {
      setAlert({ type: 'error', message: '❌ El nivel mínimo debe ser menor que el máximo' });
      return;
    }
    
    if (heightVal <= 0 || heightVal > 500) {
      setAlert({ type: 'error', message: '❌ La altura debe ser entre 1 y 500 cm' });
      return;
    }
    
    try {
      const response = await fetch(`${API_URL}/api/config`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          minLevel: minVal, 
          maxLevel: maxVal,
          tankHeight: heightVal 
        })
      });
      
      if (response.ok) {
        setAlert({ type: 'success', message: '✅ Configuración guardada correctamente' });
        setTimeout(() => setAlert(null), 3000);
      }
    } catch (error) {
      setAlert({ type: 'error', message: '❌ Error al guardar configuración' });
    }
  };

  const levelPercentage = status.level;

  const chartData = history.slice(-20).map(item => ({
    time: new Date(item.timestamp).toLocaleTimeString(),
    level: item.level
  }));

  const pumpData = [
    { name: 'Bomba ON', value: status.pumpStatus ? 1 : 0, color: COLORS.success },
    { name: 'Bomba OFF', value: status.pumpStatus ? 0 : 1, color: COLORS.danger }
  ];

  const stats = {
    avgLevel: history.length ? (history.reduce((sum, h) => sum + h.level, 0) / history.length) : 0,
    maxLevel: history.length ? Math.max(...history.map(h => h.level)) : 0,
    minLevel: history.length ? Math.min(...history.map(h => h.level)) : 0
  };

  const handleMinLevelChange = (e) => {
    const value = e.target.value;
    if (value === '') {
      setInputMinLevel('');
      return;
    }
    const numValue = parseInt(value);
    if (!isNaN(numValue) && numValue >= 0 && numValue <= 100) {
      setInputMinLevel(numValue);
    }
  };

  const handleMaxLevelChange = (e) => {
    const value = e.target.value;
    if (value === '') {
      setInputMaxLevel('');
      return;
    }
    const numValue = parseInt(value);
    if (!isNaN(numValue) && numValue >= 0 && numValue <= 100) {
      setInputMaxLevel(numValue);
    }
  };

  const handleTankHeightChange = (e) => {
    const value = e.target.value;
    if (value === '') {
      setInputTankHeight('');
      return;
    }
    const numValue = parseInt(value);
    if (!isNaN(numValue) && numValue > 0 && numValue <= 500) {
      setInputTankHeight(numValue);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh" bgcolor={COLORS.light}>
        <CircularProgress size={60} style={{ color: COLORS.primary }} />
      </Box>
    );
  }

  return (
    <Box sx={{ bgcolor: COLORS.light, minHeight: '100vh', p: 3 }}>
      <Box sx={{ mb: 4 }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" flexWrap="wrap">
          <Box>
            <Typography variant="h4" fontWeight="bold" color={COLORS.dark}>
              💧 Control de Tanque
            </Typography>
            <Typography variant="body2" color="textSecondary" sx={{ mt: 0.5 }}>
              Sistema de monitoreo y control en tiempo real
            </Typography>
          </Box>
          <Box display="flex" gap={1} alignItems="center">
            <Chip 
              label={status.pumpStatus ? "BOMBA ON" : "BOMBA OFF"} 
              size="small"
              sx={{ 
                bgcolor: status.pumpStatus ? COLORS.success : COLORS.danger,
                color: 'white',
                fontWeight: 'bold'
              }}
            />
            <Chip 
              label={`Última actualización: ${lastUpdate.toLocaleTimeString()}`} 
              size="small"
              variant="outlined"
            />
          </Box>
        </Box>
      </Box>

      {alert && (
        <Alert severity={alert.type} sx={{ mb: 3 }} onClose={() => setAlert(null)}>
          {alert.message}
        </Alert>
      )}

      <Grid container spacing={3}>
        
        {/* COLUMNA IZQUIERDA */}
        <Grid item xs={12} md={6}>
          
          {/* Tarjeta Nivel Actual */}
          <Card sx={{ p: 3, mb: 3, borderRadius: 4, boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              Nivel Actual
            </Typography>
            <Typography variant="h2" fontWeight="bold" color={COLORS.primary} sx={{ mb: 2 }}>
              {Math.round(status.level)} %
            </Typography>
            <Box sx={{ mb: 2 }}>
              <Box display="flex" justifyContent="space-between" mb={1}>
                <Typography variant="caption">0%</Typography>
                <Typography variant="caption" fontWeight="bold">50%</Typography>
                <Typography variant="caption">100%</Typography>
              </Box>
              <LinearProgress 
                variant="determinate" 
                value={levelPercentage} 
                sx={{ 
                  height: 12, 
                  borderRadius: 6,
                  bgcolor: COLORS.light,
                  '& .MuiLinearProgress-bar': {
                    bgcolor: levelPercentage > 80 ? COLORS.danger : levelPercentage < 20 ? COLORS.warning : COLORS.success,
                    borderRadius: 6
                  }
                }}
              />
            </Box>
            <Box display="flex" justifyContent="space-between" mt={2}>
              <Box textAlign="center">
                <Typography variant="caption" color="textSecondary">Mínimo</Typography>
                <Typography variant="h6" fontWeight="bold">{status.minLevel} %</Typography>
              </Box>
              <Box textAlign="center">
                <Typography variant="caption" color="textSecondary">Máximo</Typography>
                <Typography variant="h6" fontWeight="bold">{status.maxLevel} %</Typography>
              </Box>
              <Box textAlign="center">
                <Typography variant="caption" color="textSecondary">Estado</Typography>
                <Typography variant="h6" fontWeight="bold" color={levelPercentage > 80 ? COLORS.danger : levelPercentage < 20 ? COLORS.warning : COLORS.success}>
                  {levelPercentage > 80 ? 'Alto' : levelPercentage < 20 ? 'Bajo' : 'Normal'}
                </Typography>
              </Box>
            </Box>
          </Card>

          {/* Tarjeta Configuración */}
          <Card sx={{ p: 3, borderRadius: 4, boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              ⚙️ Configuración del Sistema
            </Typography>
            
            {/* Altura del Tanque */}
            <Box sx={{ mb: 3 }}>
              <Typography variant="body2" gutterBottom>📏 Altura del Tanque (cm)</Typography>
              <TextField
                fullWidth
                value={inputTankHeight}
                onChange={handleTankHeightChange}
                inputMode="numeric"
                InputProps={{
                  endAdornment: <InputAdornment position="end">cm</InputAdornment>,
                }}
                variant="outlined"
                size="small"
                sx={{ mb: 1 }}
                placeholder="Ej: 150"
              />
              <Typography variant="caption" color="textSecondary">
                Mide la altura total de tu tanque en centímetros
              </Typography>
            </Box>

            <Divider sx={{ my: 2 }} />

            {/* Umbrales */}
            <Box sx={{ mb: 3 }}>
              <Typography variant="body2" gutterBottom>⬇️ Nivel Mínimo (Encender bomba)</Typography>
              <TextField
                fullWidth
                value={inputMinLevel}
                onChange={handleMinLevelChange}
                inputMode="numeric"
                InputProps={{
                  endAdornment: <InputAdornment position="end">%</InputAdornment>,
                }}
                variant="outlined"
                size="small"
                sx={{ mb: 1 }}
                placeholder="0-100"
              />
              <Slider
                value={inputMinLevel === '' ? 0 : parseInt(inputMinLevel)}
                onChange={(_, val) => setInputMinLevel(val)}
                min={0}
                max={100}
                valueLabelDisplay="auto"
                color="warning"
              />
            </Box>

            <Box sx={{ mb: 3 }}>
              <Typography variant="body2" gutterBottom>⬆️ Nivel Máximo (Apagar bomba)</Typography>
              <TextField
                fullWidth
                value={inputMaxLevel}
                onChange={handleMaxLevelChange}
                inputMode="numeric"
                InputProps={{
                  endAdornment: <InputAdornment position="end">%</InputAdornment>,
                }}
                variant="outlined"
                size="small"
                sx={{ mb: 1 }}
                placeholder="0-100"
              />
              <Slider
                value={inputMaxLevel === '' ? 0 : parseInt(inputMaxLevel)}
                onChange={(_, val) => setInputMaxLevel(val)}
                min={0}
                max={100}
                valueLabelDisplay="auto"
                color="primary"
              />
            </Box>

            <Button 
              variant="contained" 
              fullWidth 
              onClick={saveConfig}
              sx={{ 
                bgcolor: COLORS.primary,
                textTransform: 'none',
                py: 1.5,
                '&:hover': { bgcolor: '#1d4ed8' }
              }}
            >
              Guardar Configuración
            </Button>
          </Card>
        </Grid>

        {/* COLUMNA DERECHA */}
        <Grid item xs={12} md={6}>
          
          {/* Tarjeta Estado Bomba */}
          <Card sx={{ p: 3, mb: 3, borderRadius: 4, boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              🔌 Estado de la Bomba
            </Typography>
            <Box display="flex" alignItems="center" justifyContent="space-between" flexWrap="wrap">
              <Box>
                <Typography variant="h3" fontWeight="bold" color={status.pumpStatus ? COLORS.success : COLORS.danger}>
                  {status.pumpStatus ? 'ENCENDIDA' : 'APAGADA'}
                </Typography>
                <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
                  {status.pumpStatus 
                    ? 'La bomba está funcionando. El nivel está por debajo del mínimo.' 
                    : 'La bomba está detenida. El nivel está dentro del rango configurado.'}
                </Typography>
              </Box>
              <Box sx={{ width: 120, height: 120 }}>
                <PieChart width={120} height={120}>
                  <Pie
                    data={pumpData.filter(d => d.value > 0)}
                    cx="50%"
                    cy="50%"
                    innerRadius={30}
                    outerRadius={50}
                    dataKey="value"
                  >
                    {pumpData.filter(d => d.value > 0).map((entry, index) => (
                      <Cell key={index} fill={entry.color} />
                    ))}
                  </Pie>
                </PieChart>
              </Box>
            </Box>
          </Card>

          {/* Tarjeta Historial */}
          <Card sx={{ p: 3, mb: 3, borderRadius: 4, boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="subtitle2" color="textSecondary">
                📊 Historial de Nivel
              </Typography>
              <Chip 
                label={`${history.length} lecturas`} 
                size="small" 
                variant="outlined"
              />
            </Box>
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="colorLevel" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={COLORS.primary} stopOpacity={0.3}/>
                      <stop offset="95%" stopColor={COLORS.primary} stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                  <XAxis dataKey="time" tick={{ fontSize: 11 }} />
                  <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} unit="%" />
                  <RechartsTooltip formatter={(value) => `${Math.round(value)}%`} />
                  <Area 
                    type="monotone" 
                    dataKey="level" 
                    stroke={COLORS.primary} 
                    strokeWidth={2}
                    fill="url(#colorLevel)" 
                  />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <Box textAlign="center" py={8}>
                <Typography variant="body2" color="textSecondary">
                  No hay datos aún. Esperando lecturas del sensor.
                </Typography>
              </Box>
            )}
          </Card>

          {/* Tarjeta Estadísticas */}
          <Card sx={{ p: 3, borderRadius: 4, boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              📈 Estadísticas del Día
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={4}>
                <Box textAlign="center">
                  <Typography variant="h4" fontWeight="bold" color={COLORS.primary}>
                    {Math.round(stats.avgLevel)}
                  </Typography>
                  <Typography variant="caption" color="textSecondary">Promedio (%)</Typography>
                </Box>
              </Grid>
              <Grid item xs={4}>
                <Box textAlign="center">
                  <Typography variant="h4" fontWeight="bold" color={COLORS.danger}>
                    {Math.round(stats.maxLevel)}
                  </Typography>
                  <Typography variant="caption" color="textSecondary">Máximo (%)</Typography>
                </Box>
              </Grid>
              <Grid item xs={4}>
                <Box textAlign="center">
                  <Typography variant="h4" fontWeight="bold" color={COLORS.warning}>
                    {Math.round(stats.minLevel)}
                  </Typography>
                  <Typography variant="caption" color="textSecondary">Mínimo (%)</Typography>
                </Box>
              </Grid>
            </Grid>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
}

export default App;